test('invoiceTotals: VAT is rounded per line', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1, vatRate: 21 }, // 1 cent, VAT = 0.21 → 0 cents (rounded)
      { qty: 1, unitPrice: 1, vatRate: 21 }, // 1 cent, VAT = 0.21 → 0 cents (rounded)
      { qty: 1, unitPrice: 1, vatRate: 21 }, // 1 cent, VAT = 0.21 → 0 cents (rounded)
      { qty: 1, unitPrice: 1, vatRate: 21 }, // 1 cent, VAT = 0.21 → 0 cents (rounded)
      { qty: 1, unitPrice: 1, vatRate: 21 }, // 1 cent, VAT = 0.21 → 0 cents (rounded)
    ],
  };
  const totals = invoiceTotals(invoice);
  // Each line: 1 cent, VAT 0.21 → 0 cents (banker's rounding)
  // Total VAT: 0 cents
  assert.equal(totals.vat, 0);
