test('createInvoice: tier discount is included in totals', () => {
  const result = createInvoice({
    customerId: 'C-001', // Northwind Studio, tier: gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000 cents
  // Discount: 5% of 95000 = 4750 cents
  // After discount: 95000 - 4750 = 90250 cents
  // VAT: 21% of 90250 = 18952.5 → 18953 cents
  // Total: 90250 + 18953 = 109203 cents
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('invoiceTotals: calculates VAT on line after discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Line total: 100 × 100 = 10000 cents
  // Discount: 10% of 10000 = 1000 cents
  // After discount: 10000 - 1000 = 9000 cents
  // VAT: 21% of 9000 = 1890 cents
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

