test('renderInvoiceText: shows VAT with discount and VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const text = renderInvoiceText(invoice, 'Test Customer');
  const lines = text.split('\n');

  // Line: 10 × €95.00 = €950.00 with 10% discount = €95.00
  // After discount: €855.00
  // VAT: 21% of €855.00 = €179.55
  // Total: €855.00 + €179.55 = €1,034.55
  assert.equal(lines[2], '10 × Development (hour) @ €95.00 = €950.00 (−€95.00 @ 10%)');
  assert.equal(lines[3], 'Discount: −€95.00');
  assert.equal(lines[4], 'VAT: +€179.55');
  assert.equal(lines[5], 'Total: €1,034.55');
});

test('renderInvoiceText: shows mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };

  const text = renderInvoiceText(invoice, 'Test Customer');
  const lines = text.split('\n');

  // Line 1: 5 × €95.00 = €475.00, VAT 21% = €99.75
  // Line 2: 100 × €0.37 = €37.00, VAT 9% = €3.33
  // Line 3: 1 × €600.00 = €600.00, VAT 0% = €0.00
  // Total VAT: €103.08
  // Total: €475 + €37 + €600 + €103.08 = €1,215.08
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Test Customer');
  assert.equal(lines[2], '5 × Development (hour) @ €95.00 = €475.00');
  assert.equal(lines[3], '100 × Printed flyer A4 (each) @ €0.37 = €37.00');
  assert.equal(lines[4], '1 × Brand workshop (day, VAT exempt) @ €600.00 = €600.00');
  assert.equal(lines[5], 'VAT: +€103.08');
  assert.equal(lines[6], 'Total: €1,215.08');
});

